INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 53, -416.5, 3.099, "ミッションをクリアして、\n報酬をゲットしましょう！", "カリン", "2021/10/27 14:59:59", 190802, 2, "2021/10/18 12:00:00", 2, 10077002, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 54, -416.5, 2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン", "2021/10/27 14:59:59", 190802, 3, "2021/10/18 12:00:00", 2, 10077003, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 54, -416.5, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "カリン", "2021/10/27 14:59:59", 190802, 4, "2021/10/18 12:00:00", 2, 10077004, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 57, -416.5, 0.0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", "カリン", "2021/10/27 14:59:59", 190802, 5, "2021/10/18 12:00:00", 1, 10077005, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 55, -363.0, 5.506, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", "カリン", "2021/10/27 14:59:59", 190802, 1, "2021/10/18 12:00:00", 2, 10077006, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 55, -363.0, 1.216, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", "カリン", "2021/10/27 14:59:59", 190802, 2, "2021/10/18 12:00:00", 1, 10077007, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 56, -363.0, 1.539, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "カリン", "2021/10/27 14:59:59", 190802, 3, "2021/10/18 12:00:00", 1, 10077008, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10077, 0.0, 56, -363.0, 1.875, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", "カリン", "2021/10/27 14:59:59", 190802, 4, "2021/10/18 12:00:00", 1, 10077009, 2);
