INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10086, 0.0, 54, -416.5, 2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン", "2022/02/26 14:59:59", 190801, 3, "2022/02/10 12:00:00", 2, 10086003, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10086, 0.0, 54, -416.5, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "カリン", "2022/02/26 14:59:59", 190801, 4, "2022/02/10 12:00:00", 2, 10086004, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10086, 0.0, 57, -416.5, 0.0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", "カリン", "2022/02/26 14:59:59", 190801, 5, "2022/02/10 12:00:00", 1, 10086005, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10086, 0.0, 55, -363.0, 5.506, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", "カリン", "2022/02/26 14:59:59", 190801, 1, "2022/02/10 12:00:00", 2, 10086006, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10086, 0.0, 55, -363.0, 1.216, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", "カリン", "2022/02/26 14:59:59", 190801, 2, "2022/02/10 12:00:00", 1, 10086007, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10086, 0.0, 56, -363.0, 1.539, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "カリン", "2022/02/26 14:59:59", 190801, 3, "2022/02/10 12:00:00", 1, 10086008, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (10086, 0.0, 56, -363.0, 1.875, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", "カリン", "2022/02/26 14:59:59", 190801, 4, "2022/02/10 12:00:00", 1, 10086009, 2);
