INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 53, -416.5, 3.099, "ミッションをクリアして、\n報酬をゲットしましょう！", "カリン", "2030/01/01 14:59:59", 190801, 2, "2022/04/18 15:00:00", 2, 20026002, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 54, -416.5, 2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン", "2030/01/01 14:59:59", 190801, 3, "2022/04/18 15:00:00", 2, 20026003, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 54, -416.5, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "カリン", "2030/01/01 14:59:59", 190801, 4, "2022/04/18 15:00:00", 2, 20026004, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 57, -416.5, 0.0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", "カリン", "2030/01/01 14:59:59", 190801, 5, "2022/04/18 15:00:00", 1, 20026005, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 55, -363.0, 5.506, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", "カリン", "2030/01/01 14:59:59", 190801, 1, "2022/04/18 15:00:00", 2, 20026006, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 55, -363.0, 1.216, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", "カリン", "2030/01/01 14:59:59", 190801, 2, "2022/04/18 15:00:00", 1, 20026007, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 56, -363.0, 1.539, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "カリン", "2030/01/01 14:59:59", 190801, 3, "2022/04/18 15:00:00", 1, 20026008, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (20026, 0.0, 56, -363.0, 1.875, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", "カリン", "2030/01/01 14:59:59", 190801, 4, "2022/04/18 15:00:00", 1, 20026009, 2);
